                hcnt=sum(1 for j in range(W) if g[cr][j]==2)+sum(1 for j in range(W) if g[cr][j]==3)-1
                vcnt=sum(1 for i in range(H) if g[i][cc]==2)+sum(1 for i in range(H) if g[i][cc]==3)-1
