def solve(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0]); res=[r[:] for r in g]
    # find box centers: 3s ring with 2 center
    boxes=[]
    for r in range(1,H-1):
        for c in range(1,W-1):
            if (g[r-1][c-1]==g[r-1][c]==g[r-1][c+1]==3 and
                g[r][c-1]==g[r][c+1]==3 and g[r+1][c-1]==g[r+1][c]==g[r+1][c+1]==3 and g[r][c]==2):
                boxes.append((r,c))
    # line cells: any 2 whose row or col is fully 2s (after removing box interiors)
    def full_row(r): return all(g[r][j]==2 for j in range(W))
    def full_col(c): return all(g[i][c]==2 for i in range(H))
    lines_h={r for r in range(H) if full_row(r)}
    lines_v={c for c in range(W) if full_col(c)}
    rays=[]
    for (br,bc) in boxes:
        horiz = br in lines_h
        vert  = bc in lines_v
        dirs = [(0,1),(0,-1)] if vert else [(1,0),(-1,0)]
        for dr,dc in dirs:
            rays.append((br,bc,dr,dc,horiz,vert))
    # markers: isolated 2s
    markers=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2 and
            not any(g[a][b]==3 for a in range(max(0,r-1),min(H,r+2)) for b in range(max(0,c-1),min(W,c+2))) and not (r==br and c==bc) for br,bc in []]
    # simpler: 2 with all 8 neighbors !=2 and not a box center
    boxset=set((br,bc) for br,bc in boxes)
    markers=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2 and all(not(0<=r+a<H and 0<=c+b<W and g[r+a][c+b]==2) for a in(-1,0,1) for b in(-1,0,1))]
    # perform: rays then rings then markers, painting only over 0 (and line cells at ring centers become part of ring)
    def paint(y,x,v):
        if 0<=y<H and 0<=x<W and res[y][x]!=3: res[y][x]=v
    for br,bc,dr,dc,hv,vt in rays:
        y,x=br+dr,bc+dc
        while 0<=y<H and 0<=x<W:
            if hv and y in lines_h: paint(y,x,1); break
            if vt and x in lines_v: paint(y,x,1); break
            paint(y,x,1)
            y+=dr; x+=dc
    # rings at line crossings: compute crossings by stepping rays again marking crossing points
    crossings=set()
    for br,bc,dr,dc,hv,vt in rays:
        y,x=br+dr,bc+dc
        while 0<=y<H and 0<=x<W:
            if hv and y in lines_h: crossings.add((y,x)); break
            if vt and x in lines_v: crossings.add((y,x)); break
            y+=dr; x+=dc
    for (cy,cx) in crossings:
        for a in(-1,0,1):
            for b in(-1,0,1):
                if 0<=cy+a<H and 0<=cx+b<W and res[cy+a][cx+b]!=3:
                    res[cy+a][cx+b]=1
    # marker rings
    for (mr,mc) in markers:
        for a in(-1,0,1):
            for b in(-1,0,1):
                if 0<=mr+a<H and 0<=mc+b<W and res[mr+a][mc+b]!=3:
                    res[mr+a][mc+b]=1
    return res
